/* cpu.c - the CPU illusion in a dozen lines.
   Run four copies at once:  ./cpu A & ./cpu B & ./cpu C & ./cpu D &
   One physical CPU, four programs, none of them aware of the others. */
#include <stdio.h>
#include <unistd.h>

int main(int argc, char *argv[])
{
    if (argc != 2) { fprintf(stderr, "usage: cpu <string>\n"); return 1; }
    while (1) {
        printf("%s\n", argv[1]);   /* each copy prints about once a second */
        sleep(1);                  /* and each believes it owns the machine */
    }
}

/* What the kernel keeps about one process - close to xv6's struct proc. */
enum proc_state { UNUSED, READY, RUNNING, BLOCKED, ZOMBIE };

struct context {                 /* the registers saved across a switch */
    uint64_t pc, sp;
    uint64_t regs[16];
};

struct proc {
    enum proc_state state;
    int             pid;
    struct context  ctx;         /* restored when this process runs again */
    pagetable_t     pgdir;       /* its private address space */
    struct file    *ofile[16];   /* open files: 0 stdin, 1 stdout, 2 stderr */
    struct proc    *parent;      /* who will collect its exit status */
};

int rc = fork();                    /* one call, two returns */
if (rc < 0) {
    exit(1);                        /* fork failed - no child exists */
} else if (rc == 0) {               /* the child sees 0 */
    close(STDOUT_FILENO);
    open("./out.txt", O_CREAT | O_WRONLY | O_TRUNC, 0644);
    char *args[] = { "wc", "p3.c", NULL };
    execvp(args[0], args);          /* returns only if it failed */
    printf("execvp failed\n");
} else {                            /* the parent sees the child's pid */
    int status;
    int who = wait(&status);
    printf("child %d finished\n", who);
}

/* The libc wrapper for a system call is three or four instructions. */
ssize_t write(int fd, const void *buf, size_t count)
{
    long ret;
    __asm__ volatile (
        "syscall"                    /* the trap: user mode -> kernel mode */
        : "=a" (ret)                 /* what the kernel handed back */
        : "a" (SYS_write),           /* which service is wanted */
          "D" (fd), "S" (buf), "d" (count)
        : "rcx", "r11", "memory");
    if (ret < 0) { errno = -ret; return -1; }
    return ret;
}

